import ast,hashlib,json,shlex,subprocess
from pathlib import Path
paths=[Path("docs/evidence/2026-09-10-v1-05c2b-"+name+".json") for name in ("supervisor-fds-author","shared-supervision-author","training-routing-review","native-training-tree-review")]
records=[]; allsnaps={}
for path in paths:
 commands=[]; snaps={}
 def visit(v):
  if isinstance(v,dict):
   for k,x in v.items():
    if k=="command" and isinstance(x,str): commands.append(x)
    if isinstance(k,str) and k.startswith("docs/evidence/snapshots/") and isinstance(x,str) and len(x)==64: snaps[k]=x
    if k=="snapshot" and isinstance(x,str):
     digest=v.get("snapshot_sha256",v.get("sha256"))
     if digest: snaps[x]=digest
    if k=="path" and isinstance(x,str) and x.startswith("docs/evidence/snapshots/") and "sha256" in v: snaps[x]=v["sha256"]
    visit(x)
  elif isinstance(v,list):
   for x in v: visit(x)
 visit(json.loads(path.read_bytes()))
 for cmd in commands:
  if "<<'PY'" in cmd:
   assert cmd.endswith("\nPY"),cmd
   ast.parse(cmd.split("\n",1)[1].rsplit("\nPY",1)[0])
  else:
   argv=shlex.split(cmd)
   if "-c" in argv: ast.parse(argv[argv.index("-c")+1])
 for snap,sha in snaps.items():
  raw=Path(snap).read_bytes()
  assert hashlib.sha256(raw).hexdigest()==sha,snap
  ast.parse(raw)
  assert snap not in allsnaps or allsnaps[snap]==sha
  allsnaps[snap]=sha
 records.append(dict(path=str(path),sha256=hashlib.sha256(path.read_bytes()).hexdigest(),commands_parsed=len(commands),snapshot_links_hash_matched=len(snaps)))
