for path in sorted(Path("docs/evidence/snapshots").glob("v1-05c2b-*.py")):
 raw=path.read_bytes(); ast.parse(raw)
 snapshots.append(dict(path=str(path),sha256=hashlib.sha256(raw).hexdigest(),bytes=len(raw),extent="complete source or test file"))
print(json.dumps(dict(reports=records,commands_parsed=sum(x["commands_parsed"] for x in records),unique_report_snapshot_links=len(allsnaps),all_snapshots=snapshots,all_snapshot_count=len(snapshots)),indent=2))
